<?php
declare(strict_types=1);
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Добавить пользователя</title>
<style>body{font-family:Arial,sans-serif;background:#F0F7F7;color:#1A2E35;margin:0;padding:24px}.card{max-width:720px;margin:5vh auto;background:white;padding:24px;border-radius:16px;box-shadow:0 12px 48px #0d737722}h2{color:#0A5C5F}label{display:block;margin:12px 0 5px}input{box-sizing:border-box;width:100%;padding:11px;border:1px solid #b8cece;border-radius:8px}.btn{padding:11px 18px;border:0;border-radius:8px;background:#0D7377;color:white;font-weight:bold;cursor:pointer;margin-top:16px}.muted{color:#5A7A80}.err{color:#b42318}.result{margin-top:20px;padding:16px;background:#eef8f4;border-radius:10px;overflow-wrap:anywhere}a{color:#0D7377}</style></head><body><main class="card"><h2>Добавить пользователя</h2><p class="muted">Укажите логин и ФИО. Пользователь самостоятельно задаст пароль по ссылке активации. Ссылка действует 48 часов.</p>
<form id="form"><label for="username">Логин</label><input id="username" required minlength="3" maxlength="64" pattern="[A-Za-z0-9._-]+" autocomplete="off"><label for="full_name">ФИО</label><input id="full_name" required maxlength="255"><button class="btn">Создать пользователя и получить ссылку</button></form><p id="msg" role="status"></p><section id="result" class="result" hidden><strong>Передайте эту ссылку сотруднику:</strong><p><a id="url" target="_blank" rel="noopener"></a></p><button class="btn" id="copy" type="button">Скопировать ссылку</button></section><p><a href="index.html">Вернуться к отчётам</a></p></main>
<script>
let csrf='';const msg=document.getElementById('msg'),result=document.getElementById('result'),url=document.getElementById('url');
async function status(){const r=await fetch('api.php?action=status');const d=await r.json();csrf=d.csrf||'';if(!d.authenticated){location.href='index.html';return;}if(!['admin','moderator'].includes(d.user.role)){msg.className='err';msg.textContent='Недостаточно прав.';document.getElementById('form').hidden=true;}}
document.getElementById('form').addEventListener('submit',async e=>{e.preventDefault();msg.textContent='';result.hidden=true;try{const r=await fetch('api.php?action=moderator_user_create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf,username:document.getElementById('username').value.trim(),full_name:document.getElementById('full_name').value.trim()})});const d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка создания.');url.href=d.activation_url;url.textContent=d.activation_url;result.hidden=false;msg.className='';msg.textContent='Пользователь создан. Ссылка действует 48 часов.';e.target.reset();}catch(err){msg.className='err';msg.textContent=err.message;}});
document.getElementById('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(url.href);msg.textContent='Ссылка скопирована.';}catch(e){msg.textContent='Не удалось скопировать автоматически — выделите ссылку вручную.';}});
status();
</script></body></html>